#!/usr/bin/env python3
"""Improved Deep Space Network scheduling solver."""

import json
import csv
import sys

# Load problem data
problem = json.load(open('case/problem.json'))

# Load maintenance
maintenance = []
with open('case/maintenance.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        maintenance.append({
            'antenna': row['antenna'],
            'start': int(float(row['starttime'])),
            'end': int(float(row['endtime']))
        })

# Index maintenance by antenna
maint_by_antenna = {}
for m in maintenance:
    maint_by_antenna.setdefault(m['antenna'], []).append((m['start'], m['end']))

# Build occupied intervals per antenna
occupied = {}
for m in maintenance:
    occupied.setdefault(m['antenna'], []).append((m['start'], m['end']))

all_antennas = set()
for req in problem:
    for opt in req['resources']:
        for ant in opt:
            all_antennas.add(ant)

for ant in all_antennas:
    occupied.setdefault(ant, [])

def is_available(antenna, start, end):
    """Check if [start, end) is available on given antenna."""
    for occ_start, occ_end in occupied[antenna]:
        if start < occ_end and end > occ_start:
            return False
    return True

def book(antenna, start, end):
    """Book [start, end) on antenna."""
    occupied[antenna].append((start, end))

def get_free_windows(antenna, window_start, window_end):
    """Get free time windows on an antenna within [window_start, window_end)."""
    occ = sorted(occupied[antenna])
    free = []
    cursor = window_start
    for o_start, o_end in occ:
        if o_end <= cursor:
            continue
        if o_start >= window_end:
            break
        if o_start > cursor:
            free.append((cursor, min(o_start, window_end)))
        cursor = max(cursor, o_end)
        if cursor >= window_end:
            break
    if cursor < window_end:
        free.append((cursor, window_end))
    return free

def find_slot(req):
    """Find a valid time slot and antenna for a request."""
    duration_s = int(req['duration'] * 3600)
    duration_min_s = int(req['duration_min'] * 3600)
    setup_s = req['setup_time'] * 60
    teardown_s = req['teardown_time'] * 60

    # Determine per-track minimum
    if duration_s >= 28800:
        per_track_min_s = min(duration_min_s, 14400)
    else:
        per_track_min_s = duration_min_s

    best_slot = None
    best_dur = 0

    for opt_idx, opt_ants in enumerate(req['resources']):
        is_arrayed = len(opt_ants) > 1
        combo_key = '_'.join(sorted(opt_ants))

        # Get view periods for this combination
        vp_dict = req['resource_vp_dict']

        if combo_key in vp_dict:
            vp_list = vp_dict[combo_key]
        elif not is_arrayed and opt_ants[0] in vp_dict:
            vp_list = vp_dict[opt_ants[0]]
        else:
            # Try to find common view period across all antennas
            vp_list = None
            common_vps = None
            for ant in opt_ants:
                if ant not in vp_dict:
                    vp_list = None
                    break
                ant_vps = [(vp['TRX ON'], vp['TRX OFF']) for vp in vp_dict[ant]]
                if common_vps is None:
                    common_vps = set(ant_vps)
                else:
                    common_vps &= set(ant_vps)
            if common_vps:
                vp_list = [{'TRX ON': s, 'TRX OFF': e} for s, e in common_vps]

        if not vp_list:
            continue

        req_start = req['time_window_start']
        req_end = req['time_window_end']

        for vp in vp_list:
            trx_on = vp['TRX ON']
            trx_off = vp['TRX OFF']

            # The actual available tracking window is intersection of view period and request window
            avail_start = max(trx_on, req_start + setup_s)
            avail_end = min(trx_off, req_end - teardown_s)

            if avail_end <= avail_start:
                continue

            avail_duration = avail_end - avail_start
            if avail_duration < per_track_min_s:
                continue

            # Check if antennas have any free windows
            # Find free window common to all antennas in opt_ants
            # For each antenna, get free windows and find intersection
            ant_free_windows = []
            for ant in opt_ants:
                fw = get_free_windows(ant, req_start, req_end)
                if not fw:
                    break
                ant_free_windows.append(fw)

            if len(ant_free_windows) != len(opt_ants):
                continue

            # Find common free interval across all antennas
            # Start with first antenna's free windows
            common_free = ant_free_windows[0]
            for fw_list in ant_free_windows[1:]:
                new_common = []
                for cf_start, cf_end in common_free:
                    for fw_start, fw_end in fw_list:
                        inter_start = max(cf_start, fw_start)
                        inter_end = min(cf_end, fw_end)
                        if inter_end > inter_start:
                            new_common.append((inter_start, inter_end))
                common_free = new_common
                if not common_free:
                    break

            if not common_free:
                continue

            # For each free window, try to fit a track
            for free_start, free_end in common_free:
                # The actual tracking must be within the view period AND the free window
                track_avail_start = max(avail_start, free_start + setup_s)
                track_avail_end = min(avail_end, free_end - teardown_s)

                if track_avail_end <= track_avail_start:
                    continue

                # Try to schedule full requested duration
                track_candidate_end = track_avail_start + duration_s
                if track_candidate_end <= track_avail_end:
                    tracking_on = track_avail_start
                    tracking_off = tracking_on + duration_s
                else:
                    # Try partial - schedule as much as possible
                    partial_dur = track_avail_end - track_avail_start
                    if partial_dur < per_track_min_s:
                        continue
                    # Round to nearest minute
                    partial_dur = (partial_dur // 60) * 60
                    if partial_dur < per_track_min_s:
                        continue
                    tracking_on = track_avail_start
                    tracking_off = tracking_on + partial_dur

                if tracking_off > trx_off or tracking_on < trx_on:
                    continue

                start_time = tracking_on - setup_s
                end_time = tracking_off + teardown_s

                if start_time < req_start or end_time > req_end:
                    continue

                # Verify all antennas free
                all_free = True
                for ant in opt_ants:
                    if not is_available(ant, start_time, end_time):
                        all_free = False
                        break

                if not all_free:
                    continue

                track_dur = tracking_off - tracking_on
                metric = track_dur
                if not best_slot or metric > best_dur:
                    best_slot = {
                        'antennas': opt_ants,
                        'is_arrayed': is_arrayed,
                        'START_TIME': start_time,
                        'TRACKING_ON': tracking_on,
                        'TRACKING_OFF': tracking_off,
                        'END_TIME': end_time,
                        'TRACK_ID': req['track_id'],
                        'SC': str(req['subject']),
                        'tracking_dur': track_dur,
                        'opt_idx': opt_idx
                    }
                    best_dur = metric

    return best_slot

# Sort requests: fewer options first, then higher priority
# Priority: requests with fewer antenna options first (more constrained)
def priority(req):
    return (len(req['resources']), -req['duration'])

problem_sorted = sorted(problem, key=priority)

solution_rows = []
scheduled_ids = set()

for req in problem_sorted:
    slot = find_slot(req)
    if slot:
        start = slot['START_TIME']
        end = slot['END_TIME']
        for ant in slot['antennas']:
            book(ant, start, end)

        if slot['is_arrayed']:
            for ant in slot['antennas']:
                solution_rows.append({
                    'RESOURCE': ant,
                    'SC': slot['SC'],
                    'START_TIME': start,
                    'TRACKING_ON': slot['TRACKING_ON'],
                    'TRACKING_OFF': slot['TRACKING_OFF'],
                    'END_TIME': end,
                    'TRACK_ID': slot['TRACK_ID']
                })
        else:
            solution_rows.append({
                'RESOURCE': slot['antennas'][0],
                'SC': slot['SC'],
                'START_TIME': start,
                'TRACKING_ON': slot['TRACKING_ON'],
                'TRACKING_OFF': slot['TRACKING_OFF'],
                'END_TIME': end,
                'TRACK_ID': slot['TRACK_ID']
            })
        scheduled_ids.add(req['track_id'])

# Try to schedule more requests by trying alternative placements
# Run a second pass: try remaining unscheduled requests with more flexible approach
unscheduled = [req for req in problem if req['track_id'] not in scheduled_ids]

# Sort by duration (shortest first) to fill gaps
unscheduled.sort(key=lambda r: r['duration'])

for req in unscheduled:
    slot = find_slot(req)
    if slot:
        start = slot['START_TIME']
        end = slot['END_TIME']
        for ant in slot['antennas']:
            book(ant, start, end)

        if slot['is_arrayed']:
            for ant in slot['antennas']:
                solution_rows.append({
                    'RESOURCE': ant,
                    'SC': slot['SC'],
                    'START_TIME': start,
                    'TRACKING_ON': slot['TRACKING_ON'],
                    'TRACKING_OFF': slot['TRACKING_OFF'],
                    'END_TIME': end,
                    'TRACK_ID': slot['TRACK_ID']
                })
        else:
            solution_rows.append({
                'RESOURCE': slot['antennas'][0],
                'SC': slot['SC'],
                'START_TIME': start,
                'TRACKING_ON': slot['TRACKING_ON'],
                'TRACKING_OFF': slot['TRACKING_OFF'],
                'END_TIME': end,
                'TRACK_ID': slot['TRACK_ID']
            })
        scheduled_ids.add(req['track_id'])

print(f"Scheduled {len(scheduled_ids)}/{len(problem)} requests", file=sys.stderr)
print(f"Total rows: {len(solution_rows)}", file=sys.stderr)

# Write solution
with open('solution.json', 'w') as f:
    json.dump(solution_rows, f, indent=2)

print("Wrote solution.json", file=sys.stderr)

