#!/usr/bin/env python3
"""Multi-pass DSN scheduler: large requests first, then fill gaps."""

import json
import csv
import sys

problem = json.load(open('case/problem.json'))

# Load maintenance
occupied = {}
with open('case/maintenance.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        ant = row['antenna']
        s = int(float(row['starttime']))
        e = int(float(row['endtime']))
        occupied.setdefault(ant, []).append((s, e))

for req in problem:
    for opt in req['resources']:
        for ant in opt:
            occupied.setdefault(ant, [])


def is_available(ant, s, e):
    for os, oe in occupied[ant]:
        if s < oe and e > os:
            return False
    return True


def book(ant, s, e):
    occupied[ant].append((s, e))


def get_free_windows(ant, ws, we):
    occ = sorted(occupied[ant])
    free = []
    cursor = ws
    for os, oe in occ:
        if oe <= cursor:
            continue
        if os >= we:
            break
        if os > cursor:
            free.append((cursor, min(os, we)))
        cursor = max(cursor, oe)
        if cursor >= we:
            break
    if cursor < we:
        free.append((cursor, we))
    return free


def count_valid(req):
    c = 0
    for opt in req['resources']:
        combo = '_'.join(sorted(opt))
        if combo in req['resource_vp_dict']:
            c += 1
        elif len(opt) == 1 and opt[0] in req['resource_vp_dict']:
            c += 1
    return c


def get_vp_list(req, opt_ants):
    combo = '_'.join(sorted(opt_ants))
    if combo in req['resource_vp_dict']:
        return req['resource_vp_dict'][combo]
    if len(opt_ants) == 1 and opt_ants[0] in req['resource_vp_dict']:
        return req['resource_vp_dict'][opt_ants[0]]
    return None


def try_schedule(req, target_dur=None):
    """Try to schedule req. If target_dur is None, try full then min."""
    duration_s = int(req['duration'] * 3600)
    duration_min_s = int(req['duration_min'] * 3600)
    setup_s = req['setup_time'] * 60
    teardown_s = req['teardown_time'] * 60

    if duration_s >= 28800:
        per_track_min_s = min(duration_min_s, 14400)
    else:
        per_track_min_s = duration_min_s

    durations_to_try = [duration_s, per_track_min_s] if target_dur is None else [target_dur]
    req_start = req['time_window_start']
    req_end = req['time_window_end']

    for target in durations_to_try:
        best_slot = None
        best_end = float('inf')

        for opt_ants in req['resources']:
            vp_list = get_vp_list(req, opt_ants)
            if not vp_list:
                continue

            is_arrayed = len(opt_ants) > 1

            for vp in vp_list:
                trx_on = vp['TRX ON']
                trx_off = vp['TRX OFF']

                avail_start = max(trx_on, req_start + setup_s)
                avail_end = min(trx_off, req_end - teardown_s)

                if avail_end - avail_start < target:
                    continue

                # Get common free windows across all antennas
                ant_free = []
                for ant in opt_ants:
                    fw = get_free_windows(ant, req_start, req_end)
                    if not fw:
                        break
                    ant_free.append(fw)

                if len(ant_free) != len(opt_ants):
                    continue

                # Intersect free windows
                common_free = ant_free[0]
                for afl in ant_free[1:]:
                    merged = []
                    for cfs, cfe in common_free:
                        for afs, afe in afl:
                            s = max(cfs, afs)
                            e = min(cfe, afe)
                            if e > s:
                                merged.append((s, e))
                    common_free = merged
                    if not common_free:
                        break

                if not common_free:
                    continue

                for frees, freee in common_free:
                    # START_TIME = tracking_on - setup_s >= frees
                    # tracking_on >= frees + setup_s
                    # tracking_off + teardown_s <= freee
                    # tracking_off <= freee - teardown_s
                    place_start = max(avail_start, frees + setup_s)
                    place_end = min(avail_end, freee - teardown_s)

                    if place_end - place_start < target:
                        continue

                    # Place at earliest possible position
                    tracking_on = place_start
                    tracking_off = tracking_on + target

                    if tracking_off > place_end:
                        continue
