                place_end = min(avail_end, freee - teardown_s)

                if place_end - place_start < target_dur:
                    continue

                # We'll place the track within [place_start, place_end]
                # Try to find the best position: we want it to fit without overlap
                # Since get_free_windows shows us what's free, place_start should be valid

                # But there might be multiple sub-windows within [place_start, place_end]
                # where the track fits. Let's check at the beginning of the free window.

                tracking_on = place_start
