    slot = try_schedule_at_duration(req, min_dur)
    if slot:
        commit_slot(slot, solution_rows, scheduled_ids)

print(f"Phase 1 (all min): {len(scheduled_ids)}/{len(problem)}", file=sys.stderr)

# Phase 2: Try to extend existing tracks to full requested duration
# For each scheduled request, try to re-schedule with longer duration
# We need to remove the old track and try a new placement
print(f"Phase 2: Attempting to extend tracks...", file=sys.stderr)

extended_count = 0
for req in all_reqs:
    if req['track_id'] not in scheduled_ids:
        continue

    duration_s = int(req['duration'] * 3600)
    min_dur = compute_min_duration(req)

    if min_dur >= duration_s:
        continue  # Already at full duration

    # Find existing solution rows for this track
    existing = [r for r in solution_rows if r['TRACK_ID'] == req['track_id']]
    if not existing:
        continue

    # Remove existing booking
    for row in existing:
        ant = row['RESOURCE']
        occupied[ant] = [(os, oe) for os, oe in occupied[ant]
                         if not (os == row['START_TIME'] and oe == row['END_TIME'])]

    # Remove from solution
    solution_rows = [r for r in solution_rows if r['TRACK_ID'] != req['track_id']]
    scheduled_ids.remove(req['track_id'])

    # Try to schedule at full duration or something in between
    for target in [duration_s, int((duration_s + min_dur) / 2), min_dur]:
        slot = try_schedule_at_duration(req, target)
        if slot:
