        slot = try_schedule_at_duration(req, min_dur)
        if slot:
            commit_slot(slot, solution_rows, scheduled_ids)
        # else: lost this slot, log it

print(f"Extended {extended_count} tracks", file=sys.stderr)
print(f"Total: {len(scheduled_ids)}/{len(problem)} requests, {len(solution_rows)} rows", file=sys.stderr)

# Phase 3: One more pass for unscheduled
remaining = [r for r in problem if r['track_id'] not in scheduled_ids]
remaining.sort(key=lambda r: (r['_valid_opts'], r['duration']))

for req in remaining:
    min_dur = compute_min_duration(req)
    # Try full, then min
    for target in [int(req['duration'] * 3600), min_dur]:
        slot = try_schedule_at_duration(req, target)
        if slot:
            commit_slot(slot, solution_rows, scheduled_ids)
            break

print(f"Phase 3 (remaining): added {len([r for r in remaining if r['track_id'] in scheduled_ids])}", file=sys.stderr)
print(f"Final: {len(scheduled_ids)}/{len(problem)} requests, {len(solution_rows)} rows", file=sys.stderr)

with open('solution.json', 'w') as f:
