    for os, oe in occupied[ant]:
        if s < oe and e > os:
            return False
    return True


def book(ant, s, e):
    occupied[ant].append((s, e))


def get_free_windows(ant, ws, we):
    occ = sorted(occupied[ant])
    free = []
    cursor = ws
    for os, oe in occ:
        if oe <= cursor:
            continue
        if os >= we:
            break
        if os > cursor:
            free.append((cursor, min(os, we)))
        cursor = max(cursor, oe)
        if cursor >= we:
            break
    if cursor < we:
        free.append((cursor, we))
    return free


def count_valid(req):
    c = 0
    for opt in req['resources']:
        combo = '_'.join(sorted(opt))
        if combo in req['resource_vp_dict']:
            c += 1
        elif len(opt) == 1 and opt[0] in req['resource_vp_dict']:
            c += 1
    return c


def get_vp_list(req, opt_ants):
    combo = '_'.join(sorted(opt_ants))
    if combo in req['resource_vp_dict']:
        return req['resource_vp_dict'][combo]
    if len(opt_ants) == 1 and opt_ants[0] in req['resource_vp_dict']:
        return req['resource_vp_dict'][opt_ants[0]]
    return None


def compute_min_duration(req):
    """Compute the per-track minimum duration in seconds."""
    duration_s = int(req['duration'] * 3600)
    duration_min_s = int(req['duration_min'] * 3600)
    if duration_s >= 28800:
        return min(duration_min_s, 14400)
    return duration_min_s


def try_schedule_at_duration(req, target_dur):
    """Try to schedule req with at least target_dur seconds of tracking."""
    setup_s = req['setup_time'] * 60
    teardown_s = req['teardown_time'] * 60
    req_start = req['time_window_start']
    req_end = req['time_window_end']

    best_slot = None
    best_score = -1  # Prefer later end time to leave room for others

    for opt_ants in req['resources']:
        vp_list = get_vp_list(req, opt_ants)
        if not vp_list:
            continue

        is_arrayed = len(opt_ants) > 1

        for vp in vp_list:
            trx_on = vp['TRX ON']
            trx_off = vp['TRX OFF']

            # Available tracking window
            avail_start = max(trx_on, req_start + setup_s)
            avail_end = min(trx_off, req_end - teardown_s)

            if avail_end - avail_start < target_dur:
                continue

            # Get common free windows
            ant_free = []
            for ant in opt_ants:
                fw = get_free_windows(ant, req_start, req_end)
                if not fw:
                    break
                ant_free.append(fw)

            if len(ant_free) != len(opt_ants):
                continue

            # Intersect free windows
            common_free = ant_free[0]
            for afl in ant_free[1:]:
                merged = []
                for cfs, cfe in common_free:
                    for afs, afe in afl:
                        s = max(cfs, afs)
                        e = min(cfe, afe)
                        if e > s:
                            merged.append((s, e))
                common_free = merged
                if not common_free:
                    break

            if not common_free:
                continue

            for frees, freee in common_free:
                place_start = max(avail_start, frees + setup_s)
                place_end = min(avail_end, freee - teardown_s)

                if place_end - place_start < target_dur:
                    continue

                # We'll place the track within [place_start, place_end]
                # Try to find the best position: we want it to fit without overlap
                # Since get_free_windows shows us what's free, place_start should be valid

                # But there might be multiple sub-windows within [place_start, place_end]
                # where the track fits. Let's check at the beginning of the free window.

                tracking_on = place_start
                tracking_off = tracking_on + target_dur

                if tracking_off > place_end:
                    continue
                if tracking_on < trx_on or tracking_off > trx_off:
                    continue

                start_time = tracking_on - setup_s
                end_time = tracking_off + teardown_s

                if start_time < req_start or end_time > req_end:
                    continue

                all_free = True
                for ant in opt_ants:
                    if not is_available(ant, start_time, end_time):
                        all_free = False
                        break

                if not all_free:
                    continue

                # Score: prefer later placement (leaves room before) and longer tracking
                score = end_time
                if score > best_score:
                    best_slot = {
                        'antennas': opt_ants,
                        'is_arrayed': is_arrayed,
                        'START_TIME': start_time,
                        'TRACKING_ON': tracking_on,
                        'TRACKING_OFF': tracking_off,
                        'END_TIME': end_time,
                        'TRACK_ID': req['track_id'],
                        'SC': str(req['subject']),
                        'tracking_dur': tracking_off - tracking_on,
                    }
                    best_score = score

    return best_slot


def commit_slot(slot, solution_rows, scheduled_ids):
    start = slot['START_TIME']
    end = slot['END_TIME']
    for ant in slot['antennas']:
        book(ant, start, end)

    if slot['is_arrayed']:
        for ant in slot['antennas']:
            solution_rows.append({
                'RESOURCE': ant,
                'SC': slot['SC'],
                'START_TIME': start,
                'TRACKING_ON': slot['TRACKING_ON'],
                'TRACKING_OFF': slot['TRACKING_OFF'],
                'END_TIME': end,
                'TRACK_ID': slot['TRACK_ID']
            })
    else:
        solution_rows.append({
            'RESOURCE': slot['antennas'][0],
            'SC': slot['SC'],
            'START_TIME': start,
            'TRACKING_ON': slot['TRACKING_ON'],
            'TRACKING_OFF': slot['TRACKING_OFF'],
            'END_TIME': end,
            'TRACK_ID': slot['TRACK_ID']
        })
    scheduled_ids.add(slot['TRACK_ID'])


# Precompute valid options
for req in problem:
    req['_valid_opts'] = count_valid(req)

solution_rows = []
scheduled_ids = set()

# Phase 1: Schedule all requests at minimum viable duration
# Sort by: constrained first, then by longest duration (hardest to fit)
all_reqs = sorted(problem, key=lambda r: (
    r['_valid_opts'],
    -(r['time_window_end'] - r['time_window_start']),
    -r['duration']
))

for req in all_reqs:
    min_dur = compute_min_duration(req)
    slot = try_schedule_at_duration(req, min_dur)
    if slot:
        commit_slot(slot, solution_rows, scheduled_ids)

print(f"Phase 1 (all min): {len(scheduled_ids)}/{len(problem)}", file=sys.stderr)

# Phase 2: Try to extend existing tracks to full requested duration
# For each scheduled request, try to re-schedule with longer duration
# We need to remove the old track and try a new placement
print(f"Phase 2: Attempting to extend tracks...", file=sys.stderr)

extended_count = 0
for req in all_reqs:
    if req['track_id'] not in scheduled_ids:
        continue

    duration_s = int(req['duration'] * 3600)
    min_dur = compute_min_duration(req)

    if min_dur >= duration_s:
        continue  # Already at full duration

    # Find existing solution rows for this track
    existing = [r for r in solution_rows if r['TRACK_ID'] == req['track_id']]
    if not existing:
        continue

    # Remove existing booking
    for row in existing:
        ant = row['RESOURCE']
        occupied[ant] = [(os, oe) for os, oe in occupied[ant]
                         if not (os == row['START_TIME'] and oe == row['END_TIME'])]

    # Remove from solution
    solution_rows = [r for r in solution_rows if r['TRACK_ID'] != req['track_id']]
    scheduled_ids.remove(req['track_id'])

    # Try to schedule at full duration or something in between
    for target in [duration_s, int((duration_s + min_dur) / 2), min_dur]:
        slot = try_schedule_at_duration(req, target)
        if slot:
            commit_slot(slot, solution_rows, scheduled_ids)
            if target >= duration_s:
                extended_count += 1
            break
    else:
        # If can't schedule at any duration, try-min again (should work)
        slot = try_schedule_at_duration(req, min_dur)
        if slot:
            commit_slot(slot, solution_rows, scheduled_ids)
        # else: lost this slot, log it

print(f"Extended {extended_count} tracks", file=sys.stderr)
print(f"Total: {len(scheduled_ids)}/{len(problem)} requests, {len(solution_rows)} rows", file=sys.stderr)

# Phase 3: One more pass for unscheduled
remaining = [r for r in problem if r['track_id'] not in scheduled_ids]
remaining.sort(key=lambda r: (r['_valid_opts'], r['duration']))

for req in remaining:
    min_dur = compute_min_duration(req)
    # Try full, then min
    for target in [int(req['duration'] * 3600), min_dur]:
        slot = try_schedule_at_duration(req, target)
        if slot:
            commit_slot(slot, solution_rows, scheduled_ids)
            break

print(f"Phase 3 (remaining): added {len([r for r in remaining if r['track_id'] in scheduled_ids])}", file=sys.stderr)
print(f"Final: {len(scheduled_ids)}/{len(problem)} requests, {len(solution_rows)} rows", file=sys.stderr)

with open('solution.json', 'w') as f:
    json.dump(solution_rows, f, indent=2)

print("Wrote solution.json", file=sys.stderr)

