def is_available(ant, s, e):
    for os_, oe_ in occupied[ant]:
        if s < oe_ and e > os_:
            return False
    return True


def book(ant, s, e):
    occupied[ant].append((s, e))


def unbook(ant, s, e):
    occupied[ant] = [(os_, oe_) for os_, oe_ in occupied[ant]
                     if not (os_ == s and oe_ == e)]


def get_free_windows(ant, ws, we):
    occ = sorted(occupied[ant])
    free = []
    cursor = ws
    for os_, oe_ in occ:
        if oe_ <= cursor:
            continue
        if os_ >= we:
            break
        if os_ > cursor:
            free.append((cursor, min(os_, we)))
        cursor = max(cursor, oe_)
        if cursor >= we:
            break
    if cursor < we:
        free.append((cursor, we))
    return free


def count_valid(req):
    c = 0
    for opt in req['resources']:
        combo = '_'.join(sorted(opt))
        if combo in req['resource_vp_dict']:
            c += 1
        elif len(opt) == 1 and opt[0] in req['resource_vp_dict']:
            c += 1
    return c


def get_vp_list(req, opt_ants):
    combo = '_'.join(sorted(opt_ants))
