# Process in order: most constrained first
full_dur_count = 0
for req in all_reqs:
    if req['track_id'] not in scheduled_ids:
        continue

    duration_s = int(req['duration'] * 3600)
    min_dur = compute_min_duration(req)

    if min_dur >= duration_s:
        full_dur_count += 1
        continue  # Already at full duration

    # Find current solution rows
    cur_rows = [r for r in solution_rows if r['TRACK_ID'] == req['track_id']]
    if not cur_rows:
        continue

    # Save current state
    cur_start = cur_rows[0]['START_TIME']
    cur_end = cur_rows[0]['END_TIME']

    # Try the middle duration first (halfway between min and full)
    mid_dur = (duration_s + min_dur) // 2
    mid_dur = (mid_dur // 60) * 60  # round to minute

    for try_dur in [duration_s, mid_dur]:
        # Remove old booking
        for row in cur_rows:
            unbook(row['RESOURCE'], row['START_TIME'], row['END_TIME'])

        # Try new placement
        slot = try_schedule_at_duration(req, try_dur)
        if slot:
            # Remove old rows, add new
            solution_rows = [r for r in solution_rows if r['TRACK_ID'] != req['track_id']]
