                    'START_TIME': slot['START_TIME'],
                    'TRACKING_ON': slot['TRACKING_ON'],
                    'TRACKING_OFF': slot['TRACKING_OFF'],
                    'END_TIME': slot['END_TIME'],
                    'TRACK_ID': req['track_id']
                })
        else:
            solution_rows.append({
                'RESOURCE': ant[0], 'SC': str(req['subject']),
                'START_TIME': slot['START_TIME'],
                'TRACKING_ON': slot['TRACKING_ON'],
                'TRACKING_OFF': slot['TRACKING_OFF'],
                'END_TIME': slot['END_TIME'],
                'TRACK_ID': req['track_id']
            })
        scheduled_ids.add(req['track_id'])

print(f"Pass 1: {len(scheduled_ids)}/{len(problem)}", file=sys.stderr)

# Pass 2: Try unscheduled with min duration only
remaining = [r for r in problem if r['track_id'] not in scheduled_ids]
remaining.sort(key=lambda r: (r['_valid_opts'], r['duration']))

for req in remaining:
    min_dur = compute_min_duration(req)
    slot = find_slot(req, min_dur)
    if slot:
        ant = slot['antennas']
        for a in ant:
            book(a, slot['START_TIME'], slot['END_TIME'])

        if slot['is_arrayed']:
            for a in ant:
                solution_rows.append({
                    'RESOURCE': a, 'SC': str(req['subject']),
                    'START_TIME': slot['START_TIME'],
                    'TRACKING_ON': slot['TRACKING_ON'],
                    'TRACKING_OFF': slot['TRACKING_OFF'],
                    'END_TIME': slot['END_TIME'],
                    'TRACK_ID': req['track_id']
                })
        else:
            solution_rows.append({
                'RESOURCE': ant[0], 'SC': str(req['subject']),
                'START_TIME': slot['START_TIME'],
                'TRACKING_ON': slot['TRACKING_ON'],
                'TRACKING_OFF': slot['TRACKING_OFF'],
                'END_TIME': slot['END_TIME'],
                'TRACK_ID': req['track_id']
            })
        scheduled_ids.add(req['track_id'])

print(f"Pass 2: {len(scheduled_ids)}/{len(problem)}", file=sys.stderr)

# Pass 3: Try extending from min to full for scheduled tracks
# Remove current track, try to find full-duration slot
improved = 0
for req in [r for r in sorted_reqs if r['track_id'] in scheduled_ids]:
    full_dur = int(req['duration'] * 3600)
    min_dur = compute_min_duration(req)

    if min_dur >= full_dur:
        continue

    # Check current duration
    cur_rows = [r for r in solution_rows if r['TRACK_ID'] == req['track_id']]
    if not cur_rows:
        continue

    cur_tracking = cur_rows[0]['TRACKING_OFF'] - cur_rows[0]['TRACKING_ON']
    if cur_tracking >= full_dur:
        continue

    # Remove current booking
    for r in cur_rows:
        occupied[r['RESOURCE']] = [(os_, oe_) for os_, oe_ in occupied[r['RESOURCE']]
                                    if not (os_ == r['START_TIME'] and oe_ == r['END_TIME'])]

    # Try full duration
    slot = find_slot(req, full_dur)
    if slot and slot['TRACKING_DUR'] > cur_tracking:
        solution_rows = [r for r in solution_rows if r['TRACK_ID'] != req['track_id']]
        ant = slot['antennas']
        for a in ant:
            book(a, slot['START_TIME'], slot['END_TIME'])

        if slot['is_arrayed']:
            for a in ant:
                solution_rows.append({
                    'RESOURCE': a, 'SC': str(req['subject']),
                    'START_TIME': slot['START_TIME'],
                    'TRACKING_ON': slot['TRACKING_ON'],
                    'TRACKING_OFF': slot['TRACKING_OFF'],
                    'END_TIME': slot['END_TIME'],
                    'TRACK_ID': req['track_id']
                })
        else:
            solution_rows.append({
                'RESOURCE': ant[0], 'SC': str(req['subject']),
                'START_TIME': slot['START_TIME'],
                'TRACKING_ON': slot['TRACKING_ON'],
                'TRACKING_OFF': slot['TRACKING_OFF'],
                'END_TIME': slot['END_TIME'],
                'TRACK_ID': req['track_id']
            })
        scheduled_ids.add(req['track_id'])
        improved += 1
    else:
        # Restore
        for r in cur_rows:
            occupied[r['RESOURCE']].append((r['START_TIME'], r['END_TIME']))

print(f"Pass 3 (extend): {improved} improved", file=sys.stderr)
print(f"Final: {len(scheduled_ids)}/{len(problem)} requests, {len(solution_rows)} rows", file=sys.stderr)

with open('solution.json', 'w') as f:
    json.dump(solution_rows, f, indent=2)

