"""Hybrid DSN scheduler: full duration for high-value, min for rest."""

import json
import csv
import sys
import math

problem = json.load(open('case/problem.json'))

occupied = {}
with open('case/maintenance.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        ant = row['antenna']
        s = int(float(row['starttime']))
        e = int(float(row['endtime']))
        occupied.setdefault(ant, []).append((s, e))

for req in problem:
    for opt in req['resources']:
        for ant in opt:
            occupied.setdefault(ant, [])


def is_available(ant, s, e):
    for os_, oe_ in occupied[ant]:
        if s < oe_ and e > os_:
            return False
    return True


def book(ant, s, e):
    occupied[ant].append((s, e))


def unbook(ant, s, e):
    occupied[ant] = [(os_, oe_) for os_, oe_ in occupied[ant]
                     if not (os_ == s and oe_ == e)]


def get_free_windows(ant, ws, we):
    occ = sorted(occupied[ant])
    free = []
    cursor = ws
    for os_, oe_ in occ:
        if oe_ <= cursor:
            continue
        if os_ >= we:
            break
        if os_ > cursor:
            free.append((cursor, min(os_, we)))
        cursor = max(cursor, oe_)
        if cursor >= we:
            break
    if cursor < we:
        free.append((cursor, we))
    return free


def count_valid(req):
    c = 0
    for opt in req['resources']:
        combo = '_'.join(sorted(opt))
        if combo in req['resource_vp_dict']:
            c += 1
        elif len(opt) == 1 and opt[0] in req['resource_vp_dict']:
            c += 1
    return c


def get_vp_list(req, opt_ants):
    combo = '_'.join(sorted(opt_ants))
    if combo in req['resource_vp_dict']:
        return req['resource_vp_dict'][combo]
    if len(opt_ants) == 1 and opt_ants[0] in req['resource_vp_dict']:
        return req['resource_vp_dict'][opt_ants[0]]
    return None


def compute_min_duration(req):
    duration_s = int(req['duration'] * 3600)
    duration_min_s = int(req['duration_min'] * 3600)
    if duration_s >= 28800:
        return min(duration_min_s, 14400)
    return duration_min_s


def find_slot_general(req, target_dur, allow_shorter=True, avoid_antennas=None):
    """
    Find a slot for req with the specified duration.
    If allow_shorter and no slot found for target_dur, try shorter (down to min).
    """
    setup_s = req['setup_time'] * 60
    teardown_s = req['teardown_time'] * 60
    req_start = req['time_window_start']
    req_end = req['time_window_end']
    min_dur = compute_min_duration(req)

    # Durations to try: only try requested and minimum
    if allow_shorter and target_dur > min_dur:
        durs_to_try = [target_dur, min_dur]
    else:
        durs_to_try = [target_dur]

    for dur in durs_to_try:
        best_slot = None
        best_score = -1

        for opt_ants in req['resources']:
            if avoid_antennas and opt_ants[0] in avoid_antennas:
                continue

            vp_list = get_vp_list(req, opt_ants)
            if not vp_list:
                continue

            is_arrayed = len(opt_ants) > 1

            for vp in vp_list:
                trx_on = vp['TRX ON']
                trx_off = vp['TRX OFF']

                avail_start = max(trx_on, req_start + setup_s)
                avail_end = min(trx_off, req_end - teardown_s)

                if avail_end - avail_start < dur:
                    continue

                # Get free windows for all antennas
                ant_free = []
                for ant in opt_ants:
                    fw = get_free_windows(ant, req_start, req_end)
                    if not fw:
                        break
                    ant_free.append(fw)

                if len(ant_free) != len(opt_ants):
                    continue

                # Intersect
                common_free = ant_free[0]
                for afl in ant_free[1:]:
                    merged = []
                    for cfs, cfe in common_free:
                        for afs, afe in afl:
                            s = max(cfs, afs)
                            e = min(cfe, afe)
                            if e > s:
                                merged.append((s, e))
                    common_free = merged
                    if not common_free:
                        break

                if not common_free:
                    continue

                for frees, freee in common_free:
                    place_start = max(avail_start, frees + setup_s)
                    place_end = min(avail_end, freee - teardown_s)

                    if place_end - place_start < dur:
                        continue

                    tracking_on = place_start
                    tracking_off = tracking_on + dur

                    if tracking_off > place_end:
                        continue
                    if tracking_on < trx_on or tracking_off > trx_off:
                        continue

                    start_time = tracking_on - setup_s
                    end_time = tracking_off + teardown_s

                    if start_time < req_start or end_time > req_end:
                        continue

                    all_free = True
                    for ant in opt_ants:
                        if not is_available(ant, start_time, end_time):
                            all_free = False
                            break

                    if not all_free:
                        continue

                    tracking_dur = tracking_off - tracking_on
                    score = tracking_dur
                    if score > best_score:
                        best_slot = {
                            'antennas': opt_ants,
                            'is_arrayed': is_arrayed,
                            'START_TIME': start_time,
                            'TRACKING_ON': tracking_on,
                            'TRACKING_OFF': tracking_off,
                            'END_TIME': end_time,
                            'TRACK_ID': req['track_id'],
                            'SC': str(req['subject']),
                            'tracking_dur': tracking_dur,
                        }
                        best_score = score

        if best_slot:
            return best_slot

    return None


def commit_slot(slot, rows, ids_set):
    start = slot['START_TIME']
    end = slot['END_TIME']
    for ant in slot['antennas']:
        book(ant, start, end)
    if slot['is_arrayed']:
        for ant in slot['antennas']:
            rows.append({
                'RESOURCE': ant, 'SC': slot['SC'],
                'START_TIME': start, 'TRACKING_ON': slot['TRACKING_ON'],
                'TRACKING_OFF': slot['TRACKING_OFF'], 'END_TIME': end,
                'TRACK_ID': slot['TRACK_ID']
            })
    else:
        rows.append({
            'RESOURCE': slot['antennas'][0], 'SC': slot['SC'],
            'START_TIME': start, 'TRACKING_ON': slot['TRACKING_ON'],
            'TRACKING_OFF': slot['TRACKING_OFF'], 'END_TIME': end,
            'TRACK_ID': slot['TRACK_ID']
        })
    ids_set.add(slot['TRACK_ID'])


for req in problem:
    req['_valid_opts'] = count_valid(req)

solution_rows = []
scheduled_ids = set()

# Strategy:
# 1. First pass: MOST constrained first, try FULL duration
# 2. If full duration fails, try min duration
# This way we favor constrained requests getting full time

all_reqs = sorted(problem, key=lambda r: (
    r['_valid_opts'],
    -(r['time_window_end'] - r['time_window_start']),
    -r['duration']
))

for req in all_reqs:
    full_dur = int(req['duration'] * 3600)
    slot = find_slot_general(req, full_dur, allow_shorter=True)
    if slot:
        commit_slot(slot, solution_rows, scheduled_ids)

print(f"Pass 1: {len(scheduled_ids)}/{len(problem)}", file=sys.stderr)

# 2. Second pass: try to REPLACE shorter tracks with full duration
# For tracks where allocated < requested, try to find a new full-duration slot
# by temporarily freeing their current slot

full_count = 0
improved = 0
for req in all_reqs:
    if req['track_id'] not in scheduled_ids:
        continue
    full_dur = int(req['duration'] * 3600)
    min_dur = compute_min_duration(req)

    if min_dur >= full_dur:
        full_count += 1
        continue

    # Check current allocation
    cur_rows = [r for r in solution_rows if r['TRACK_ID'] == req['track_id']]
    if not cur_rows:
        continue
    cur_dur = cur_rows[0]['TRACKING_OFF'] - cur_rows[0]['TRACKING_ON']

    if cur_dur >= full_dur:
        full_count += 1
        continue

    # Try to improve: remove current, try full duration
    for r in cur_rows:
        unbook(r['RESOURCE'], r['START_TIME'], r['END_TIME'])

    new_slot = find_slot_general(req, full_dur, allow_shorter=True)
    if new_slot and new_slot['tracking_dur'] > cur_dur:
        solution_rows = [r for r in solution_rows if r['TRACK_ID'] != req['track_id']]
        # Don't unbook - already done above
        commit_slot(new_slot, solution_rows, scheduled_ids)
        improved += 1
    else:
        # Restore
        for r in cur_rows:
            book(r['RESOURCE'], r['START_TIME'], r['END_TIME'])

print(f"Pass 2: {full_count} at full, {improved} improved, total {len(scheduled_ids)}", file=sys.stderr)

# 3. Third pass: try remaining unscheduled at minimum duration
remaining = [r for r in problem if r['track_id'] not in scheduled_ids]
remaining.sort(key=lambda r: (r['_valid_opts'], r['duration']))

for req in remaining:
    min_dur = compute_min_duration(req)
    slot = find_slot_general(req, min_dur, allow_shorter=False)
    if slot:
        commit_slot(slot, solution_rows, scheduled_ids)

print(f"Pass 3: {len(scheduled_ids)}/{len(problem)}", file=sys.stderr)

print(f"Final: {len(scheduled_ids)}/{len(problem)} requests, {len(solution_rows)} rows", file=sys.stderr)

with open('solution.json', 'w') as f:
    json.dump(solution_rows, f, indent=2)

print("Wrote solution.json", file=sys.stderr)

