    if req['track_id'] not in scheduled_ids:
        continue
    full_dur = int(req['duration'] * 3600)
    min_dur = compute_min_duration(req)
    if min_dur >= full_dur:
        continue

    cur_rows = [r for r in solution_rows if r['TRACK_ID'] == req['track_id']]
    if not cur_rows:
        continue
