import csv
import sys

problem = json.load(open('case/problem.json'))

occupied = {}
with open('case/maintenance.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        ant = row['antenna']
        s = int(float(row['starttime']))
        e = int(float(row['endtime']))
        occupied.setdefault(ant, []).append((s, e))

for req in problem:
    for opt in req['resources']:
        for ant in opt:
            occupied.setdefault(ant, [])


def is_available(ant, s, e):
    for os_, oe_ in occupied[ant]:
        if s < oe_ and e > os_:
            return False
    return True


def find_next_available(ant, s, e):
    """Find if [s, e) is available. If not, find the earliest start > s that works.
    Returns (start, end) or None."""
    occ = sorted(occupied[ant])
    for os_, oe_ in occ:
        if s < oe_ and e > os_:
            # Overlap - shift past this occupied interval
            s = oe_
            e = s + (e - s - (oe_ - s))  # maintain duration
            return find_next_available(ant, s, e)
    return (s, e) if s < e else None


def book(ant, s, e):
    occupied[ant].append((s, e))


def get_free_windows(ant, ws, we):
    occ = sorted(occupied[ant])
    free = []
    cursor = ws
    for os_, oe_ in occ:
        if oe_ <= cursor:
            continue
        if os_ >= we:
            break
        if os_ > cursor:
            free.append((cursor, min(os_, we)))
        cursor = max(cursor, oe_)
        if cursor >= we:
            break
    if cursor < we:
        free.append((cursor, we))
    return free


def count_valid(req):
    c = 0
    for opt in req['resources']:
        combo = '_'.join(sorted(opt))
        if combo in req['resource_vp_dict']:
            c += 1
        elif len(opt) == 1 and opt[0] in req['resource_vp_dict']:
            c += 1
    return c


def get_vp_list(req, opt_ants):
    combo = '_'.join(sorted(opt_ants))
    if combo in req['resource_vp_dict']:
        return req['resource_vp_dict'][combo]
    if len(opt_ants) == 1 and opt_ants[0] in req['resource_vp_dict']:
        return req['resource_vp_dict'][opt_ants[0]]
    return None


def compute_min_duration(req):
    duration_s = int(req['duration'] * 3600)
    duration_min_s = int(req['duration_min'] * 3600)
    if duration_s >= 28800:
        return min(duration_min_s, 14400)
    return duration_min_s


def find_slot(req, target_dur):
    """Find a slot with aggressive position search."""
    setup_s = req['setup_time'] * 60
    teardown_s = req['teardown_time'] * 60
    req_start = req['time_window_start']
    req_end = req['time_window_end']

    best_slot = None

    for opt_ants in req['resources']:
        vp_list = get_vp_list(req, opt_ants)
        if not vp_list:
            continue

        is_arrayed = len(opt_ants) > 1

        for vp in vp_list:
            trx_on = vp['TRX ON']
            trx_off = vp['TRX OFF']

            # Intersection of VP and (request window minus setup/teardown)
            avail_start = max(trx_on + setup_s, req_start + setup_s)
            avail_end = min(trx_off - teardown_s, req_end - teardown_s)

            if avail_end - avail_start < target_dur:
                continue

            # Get free windows
            ant_free = []
            for ant in opt_ants:
                fw = get_free_windows(ant, req_start, req_end)
                if not fw:
                    break
                ant_free.append(fw)

            if len(ant_free) != len(opt_ants):
                continue

            # Intersect
            common_free = ant_free[0]
            for afl in ant_free[1:]:
                merged = []
                for cfs, cfe in common_free:
                    for afs, afe in afl:
                        s = max(cfs, afs)
                        e = min(cfe, afe)
                        if e > s:
                            merged.append((s, e))
                common_free = merged
                if not common_free:
                    break

            if not common_free:
                continue

            for frees, freee in common_free:
                # The track [start, end) must fit in [frees, freee)
                # start = tracking_on - setup >= frees -> tracking_on >= frees + setup
                # end = tracking_off + teardown <= freee -> tracking_off <= freee - teardown
                place_start = max(avail_start, frees + setup_s)
                place_end = min(avail_end, freee - teardown_s)

                if place_end - place_start < target_dur:
                    continue

                # Try earliest position first, then scan forward
                tracking_on = place_start
                tracking_off = tracking_on + target_dur

