                    if tracking_on < trx_on or tracking_off > trx_off:
                        tracking_on += 60
                        tracking_off = tracking_on + target_dur
                        continue

                    start_time = tracking_on - setup_s
                    end_time = tracking_off + teardown_s

                    if start_time < req_start or end_time > req_end:
                        tracking_on += 60
                        tracking_off = tracking_on + target_dur
                        continue

