                            'antennas': opt_ants,
                            'is_arrayed': is_arrayed,
                            'START_TIME': start_time,
                            'TRACKING_ON': tracking_on,
                            'TRACKING_OFF': tracking_off,
                            'END_TIME': end_time,
                            'TRACKING_DUR': tracking_off - tracking_on,
                        }
                        return best_slot  # Return immediately on first valid

                    # Shift past the blocking interval if we found one
                    if first_blocked_ant and blocked_end > 0:
                        # The blocked_end is where the blocking track ends
