# Pass 2: Try unscheduled with min duration
remaining = [r for r in problem if r['track_id'] not in scheduled_ids]
# Process shortest duration first (easiest to fit in remaining gaps)
remaining.sort(key=lambda r: (r['time_window_end'] - r['time_window_start'], r['duration']))

for req in remaining:
    min_dur = compute_min_duration(req)
    slot = find_slot(req, min_dur)
    if slot:
