print(f"Pass 2: {len(solution_rows)} rows, {len(scheduled_ids)} tracks", file=sys.stderr)

# Pass 3: Try to replace min-duration tracks with full-duration
# Only try for tracks that are not at full duration
improved = 0
for req in sorted_reqs:
