#!/usr/bin/env python3
"""DSN scheduler: pack efficiently, maximize hours + count."""

import json
import csv
import sys

problem = json.load(open('case/problem.json'))

# Initialize occupied with maintenance windows
occupied = {}
with open('case/maintenance.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        ant = row['antenna']
        s = int(float(row['starttime']))
        e = int(float(row['endtime']))
        occupied.setdefault(ant, []).append((s, e))

for req in problem:
    for opt in req['resources']:
        for ant in opt:
            occupied.setdefault(ant, [])


def book(ant, s, e):
    occupied[ant].append((s, e))


def get_free_windows(ant, ws, we):
    occ = sorted(occupied[ant])
    free = []
    cursor = ws
    for os_, oe_ in occ:
        if oe_ <= cursor:
            continue
        if os_ >= we:
            break
        if os_ > cursor:
            # Start of free window might have some tracking if cursor < os_
            free_start = max(cursor, ws)
            free_end = min(os_, we)
            if free_end > free_start:
                free.append((free_start, free_end))
        cursor = max(cursor, oe_)
        if cursor >= we:
            break
    if cursor < we:
        free.append((cursor, we))
    return free


def count_valid(req):
    c = 0
    for opt in req['resources']:
        combo = '_'.join(sorted(opt))
        if combo in req['resource_vp_dict']:
            c += 1
        elif len(opt) == 1 and opt[0] in req['resource_vp_dict']:
            c += 1
    return c


def get_vp_list(req, opt_ants):
    combo = '_'.join(sorted(opt_ants))
    if combo in req['resource_vp_dict']:
        return req['resource_vp_dict'][combo]
    if len(opt_ants) == 1 and opt_ants[0] in req['resource_vp_dict']:
        return req['resource_vp_dict'][opt_ants[0]]
    return None


def compute_min_duration(req):
    duration_s = int(req['duration'] * 3600)
    duration_min_s = int(req['duration_min'] * 3600)
    if duration_s >= 28800:
        return min(duration_min_s, 14400)
    return duration_min_s


def find_best_slot(req, target_dur):
    """
    Find the best slot for req with target_dur tracking seconds.
    Returns (slot, metric) where metric sorts slots by desirability.
    """
    setup_s = req['setup_time'] * 60
    teardown_s = req['teardown_time'] * 60
    req_start = req['time_window_start']
    req_end = req['time_window_end']

    best_slot = None
    best_metric = -1  # We want to maximize hours, prefer leaving gaps

    for opt_ants in req['resources']:
        vp_list = get_vp_list(req, opt_ants)
        if not vp_list:
            continue

        is_arrayed = len(opt_ants) > 1

        for vp in vp_list:
            trx_on = vp['TRX ON']
            trx_off = vp['TRX OFF']

            # tracking_on can be from trx_on, but start_time = tracking_on - setup must be >= req_start
            earliest_tracking = max(trx_on, req_start + setup_s)
            # tracking_off can go up to trx_off, but end_time = tracking_off + teardown must be <= req_end
            latest_tracking = min(trx_off, req_end - teardown_s)

            if latest_tracking - earliest_tracking < target_dur:
                continue

            # Get free windows for all antennas
            ant_free = []
            for ant in opt_ants:
                fw = get_free_windows(ant, req_start, req_end)
                if not fw:
                    break
                ant_free.append(fw)

            if len(ant_free) != len(opt_ants):
                continue

            # Intersect free windows across antennas
            common_free = ant_free[0]
            for afl in ant_free[1:]:
                merged = []
                for cfs, cfe in common_free:
                    for afs, afe in afl:
                        s = max(cfs, afs)
                        e = min(cfe, afe)
                        if e > s:
                            merged.append((s, e))
                common_free = merged
                if not common_free:
                    break

            if not common_free:
                continue

            for frees, freee in common_free:
                # Track's full interval [start_time, end_time) must fit in [frees, freee)
                # start_time = tracking_on - setup >= frees -> tracking_on >= frees + setup
                # end_time = tracking_off + teardown <= freee -> tracking_off <= freee - teardown
                place_earliest = max(earliest_tracking, frees + setup_s)
                place_latest = min(latest_tracking, freee - teardown_s)

                if place_latest - place_earliest < target_dur:
                    continue

                # Try the earliest position
                tracking_on = place_earliest
                tracking_off = tracking_on + target_dur

                if tracking_off > place_latest:
                    continue

                start_time = tracking_on - setup_s
                end_time = tracking_off + teardown_s

                if start_time < req_start or end_time > req_end:
                    continue
                if tracking_on < trx_on or tracking_off > trx_off:
                    continue

                # All antennas must be free
                all_free = True
                for ant in opt_ants:
                    for os_, oe_ in occupied[ant]:
                        if start_time < oe_ and end_time > os_:
                            all_free = False
                            break
                    if not all_free:
                        break

                if not all_free:
                    continue

                # Calculate a metric: prefer leaving small gaps filled,
                # prefer later placement (leaves earlier room for others)
                # Actually, just use the end_time as metric - later is better
                # because it leaves room before for other requests
                metric = end_time * 1000 + target_dur
                if metric > best_metric:
                    best_slot = {
                        'antennas': opt_ants,
                        'is_arrayed': is_arrayed,
                        'START_TIME': start_time,
                        'TRACKING_ON': tracking_on,
                        'TRACKING_OFF': tracking_off,
                        'END_TIME': end_time,
                        'TRACKING_DUR': tracking_off - tracking_on,
                    }
                    best_metric = metric

    return best_slot


for req in problem:
    req['_valid_opts'] = count_valid(req)

solution_rows = []
scheduled_ids = set()


def add_to_solution(req, slot):
    for a in slot['antennas']:
        book(a, slot['START_TIME'], slot['END_TIME'])
    if slot['is_arrayed']:
        for a in slot['antennas']:
            solution_rows.append({
                'RESOURCE': a, 'SC': str(req['subject']),
                'START_TIME': slot['START_TIME'],
                'TRACKING_ON': slot['TRACKING_ON'],
                'TRACKING_OFF': slot['TRACKING_OFF'],
                'END_TIME': slot['END_TIME'],
                'TRACK_ID': req['track_id']
            })
    else:
        solution_rows.append({
            'RESOURCE': slot['antennas'][0], 'SC': str(req['subject']),
            'START_TIME': slot['START_TIME'],
            'TRACKING_ON': slot['TRACKING_ON'],
            'TRACKING_OFF': slot['TRACKING_OFF'],
            'END_TIME': slot['END_TIME'],
            'TRACK_ID': req['track_id']
        })
    scheduled_ids.add(req['track_id'])


# Sort: more constrained first
sorted_reqs = sorted(problem, key=lambda r: (
    r['_valid_opts'],
    r['time_window_end'] - r['time_window_start'],
    -r['duration']
))

# Pass 1: Full duration first, fallback to min
for req in sorted_reqs:
    full_dur = int(req['duration'] * 3600)
    min_dur = compute_min_duration(req)

    slot = find_best_slot(req, full_dur)
    if not slot and min_dur < full_dur:
        slot = find_best_slot(req, min_dur)
    if slot:
        add_to_solution(req, slot)

print(f"Pass 1: {len(solution_rows)} rows, {len(scheduled_ids)} tracks", file=sys.stderr)

# Pass 2: Try unscheduled at minimum
remaining = [r for r in problem if r['track_id'] not in scheduled_ids]
remaining.sort(key=lambda r: (r['_valid_opts'], r['duration']))

for req in remaining:
    min_dur = compute_min_duration(req)
    slot = find_best_slot(req, min_dur)
    if slot:
        add_to_solution(req, slot)

print(f"Pass 2: {len(solution_rows)} rows, {len(scheduled_ids)} tracks", file=sys.stderr)

# Pass 3: For min-duration tracks, try extending by removing and re-scheduling
sorted_partial = [r for r in sorted_reqs if r['track_id'] in scheduled_ids]
for req in sorted_partial:
    full_dur = int(req['duration'] * 3600)
    min_dur = compute_min_duration(req)
    if min_dur >= full_dur:
        continue

    cur_rows = [r for r in solution_rows if r['TRACK_ID'] == req['track_id']]
    if not cur_rows:
        continue
    cur_tracking = cur_rows[0]['TRACKING_OFF'] - cur_rows[0]['TRACKING_ON']
    if cur_tracking >= full_dur:
        continue

    # Try to extend by looking for a new slot
    saved = [(r['RESOURCE'], r['START_TIME'], r['END_TIME']) for r in cur_rows]

    # Remove current
    for ant, s, e in saved:
        occupied[ant] = [(os_, oe_) for os_, oe_ in occupied[ant] if not (os_ == s and oe_ == e)]

    # Try full
    slot = find_best_slot(req, full_dur)
    if slot and slot['TRACKING_DUR'] > cur_tracking:
        solution_rows = [r for r in solution_rows if r['TRACK_ID'] != req['track_id']]
        add_to_solution(req, slot)
    else:
        # Restore
        for ant, s, e in saved:
            occupied[ant].append((s, e))

print(f"Pass 3 complete", file=sys.stderr)
print(f"Final: {len(solution_rows)} rows, {len(scheduled_ids)} tracks", file=sys.stderr)

with open('solution.json', 'w') as f:
    json.dump(solution_rows, f, indent=2)

print("Wrote solution.json", file=sys.stderr)

