"""DSN scheduler: pack efficiently, maximize hours + count."""

import json
import csv
import sys

problem = json.load(open('case/problem.json'))

# Initialize occupied with maintenance windows
occupied = {}
with open('case/maintenance.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        ant = row['antenna']
        s = int(float(row['starttime']))
        e = int(float(row['endtime']))
