            'RESOURCE': slot['antennas'][0], 'SC': str(req['subject']),
            'START_TIME': slot['START_TIME'],
            'TRACKING_ON': slot['TRACKING_ON'],
            'TRACKING_OFF': slot['TRACKING_OFF'],
            'END_TIME': slot['END_TIME'],
            'TRACK_ID': req['track_id']
