"""DSN scheduler - multi-track with post-processing and extension."""

import json
import csv
import sys
from collections import defaultdict

problem = json.load(open('case/problem.json'))

occupied = {}
with open('case/maintenance.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        ant = row['antenna']
        s = int(float(row['starttime']))
        e = int(float(row['endtime']))
