    if len(opt_ants) == 1 and opt_ants[0] in req['resource_vp_dict']:
        return req['resource_vp_dict'][opt_ants[0]]
    return None


def compute_min_duration(req):
    duration_s = int(req['duration'] * 3600)
    duration_min_s = int(req['duration_min'] * 3600)
    if duration_s >= 28800:
        return min(duration_min_s, 14400)
    return duration_min_s


def find_slot(req, target_dur):
