#!/usr/bin/env python3
"""DSN scheduler - multi-track for max coverage + competitive hours."""

import json, csv, sys
from collections import defaultdict

problem = json.load(open('case/problem.json'))

occupied = {}
with open('case/maintenance.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        ant = row['antenna']
        occupied.setdefault(ant, []).append((int(float(row['starttime'])), int(float(row['endtime']))))

for req in problem:
    for opt in req['resources']:
        for ant in opt:
            occupied.setdefault(ant, [])

def is_free(ant, s, e):
    return not any(s < oe and e > os for os, oe in occupied[ant])

def book(ant, s, e):
    occupied[ant].append((s, e))

def get_free(ant, ws, we):
    occ = sorted(occupied[ant])
    free, cursor = [], ws
    for os, oe in occ:
        if oe <= cursor: continue
        if os >= we: break
        if os > cursor: free.append((cursor, min(os, we)))
        cursor = max(cursor, oe)
    if cursor < we: free.append((cursor, we))
    return free

def valid_opts(req):
    c = 0
    for opt in req['resources']:
        combo = '_'.join(sorted(opt))
        if combo in req['resource_vp_dict'] or (len(opt)==1 and opt[0] in req['resource_vp_dict']):
            c += 1
    return c

def get_vps(req, ants):
    combo = '_'.join(sorted(ants))
    if combo in req['resource_vp_dict']: return req['resource_vp_dict'][combo]
    if len(ants)==1 and ants[0] in req['resource_vp_dict']: return req['resource_vp_dict'][ants[0]]
    return None

def min_dur(req):
    ds = int(req['duration'] * 3600)
    dms = int(req['duration_min'] * 3600)
    return min(dms, 14400) if ds >= 28800 else dms

def find_track(req, target):
    setup, teardown = req['setup_time']*60, req['teardown_time']*60
    ws, we = req['time_window_start'], req['time_window_end']
    for ants in req['resources']:
        vps = get_vps(req, ants)
        if not vps: continue
        arr = len(ants) > 1
        for vp in vps:
            lo = max(vp['TRX ON'], ws + setup)
            hi = min(vp['TRX OFF'], we - teardown)
            if hi - lo < target: continue
            af = []
            for a in ants:
                fw = get_free(a, ws, we)
                if not fw: break
                af.append(fw)
            if len(af) != len(ants): continue
            c = af[0]
            for fl in af[1:]:
                m = []
                for cs, ce in c:
                    for fs, fe in fl:
                        s, e = max(cs, fs), min(ce, fe)
                        if e > s: m.append((s, e))
                c = m
                if not c: break
            if not c: continue
            for frees, freee in c:
                plo = max(lo, frees + setup)
                phi = min(hi, freee - teardown)
                if phi - plo < target: continue
                ton, toff = plo, plo + target
                if toff > phi: continue
                st, et = ton - setup, toff + teardown
                if st < ws or et > we: continue
                ok = all(is_free(a, st, et) for a in ants)
                if ok: return {'ants': ants, 'arr': arr, 'st': st, 'ton': ton, 'toff': toff, 'et': et}
    return None

# Precompute valid options
for req in problem:
    req['_vopts'] = valid_opts(req)

rows, alloc = [], {}

def book_it(req, slot, new_tid=True):
    for a in slot['ants']: book(a, slot['st'], slot['et'])
    tid = req['track_id']
    if slot['arr']:
        for a in slot['ants']:
            rows.append({'RESOURCE': a, 'SC': str(req['subject']), 'START_TIME': slot['st'],
                         'TRACKING_ON': slot['ton'], 'TRACKING_OFF': slot['toff'],
                         'END_TIME': slot['et'], 'TRACK_ID': tid})
    else:
        rows.append({'RESOURCE': slot['ants'][0], 'SC': str(req['subject']), 'START_TIME': slot['st'],
                     'TRACKING_ON': slot['ton'], 'TRACKING_OFF': slot['toff'],
                     'END_TIME': slot['et'], 'TRACK_ID': tid})
    alloc[tid] = alloc.get(tid, 0) + slot['toff'] - slot['ton']

# Sort by: constrained first, then long duration, then tight window
order = sorted(problem, key=lambda r: (r['_vopts'], -r['duration'], r['time_window_end'] - r['time_window_start']))

# Pass 1: All requests at minimum viable duration
for req in order:
    s = find_track(req, min_dur(req))
    if s: book_it(req, s)

print(f"P1: {len(rows)}r {len(alloc)}t", file=sys.stderr)

# Pass 2: Add second tracks for undersatisfied requests
add = 0
for req in order:
    tid = req['track_id']
    if tid not in alloc: continue
    full = int(req['duration'] * 3600)
    have = alloc[tid]
    if have >= full: continue
    want = max(full - have, min_dur(req))
    s = find_track(req, want)
    if not s: s = find_track(req, min_dur(req))
    if s: book_it(req, s); add += 1

print(f"P2: +{add}t {len(rows)}r", file=sys.stderr)

# Pass 3: Try remaining unscheduled at minimum
rem = [r for r in problem if r['track_id'] not in alloc]
rem.sort(key=lambda r: r['_vopts'])
a3 = 0
for req in rem:
    s = find_track(req, min_dur(req))
    if s: book_it(req, s); a3 += 1

print(f"P3: +{a3}t", file=sys.stderr)

# Post-process: fix invalid arrayed logical tracks
req_m = {r['track_id']: r for r in problem}
lg = defaultdict(list)
for r in rows: lg[(r['TRACK_ID'], r['START_TIME'], r['END_TIME'])].append(r)
new_rows = []
for (tid, st, et), grp in lg.items():
    ant_sorted = sorted(r['RESOURCE'] for r in grp)
    combo = '_'.join(ant_sorted)
    valid = combo in req_m[tid]['resource_vp_dict'] or (len(ant_sorted)==1 and ant_sorted[0] in req_m[tid]['resource_vp_dict'])
    new_rows.append(grp[0]) if not valid else new_rows.extend(grp)
rows = new_rows

uniq = len(set(r['TRACK_ID'] for r in rows))
print(f"Final: {len(rows)}r {uniq}t", file=sys.stderr)
json.dump(rows, open('solution.json', 'w'), indent=2)
print("Done", file=sys.stderr)
